package cpamp

import (
	"math"
	"sort"
)

const EstimatorV2 = "quota-estimator-v2"
const EstimatorVersion = "quota-estimator-v3"

const quotaClockMarginMS = int64(5000)

// quotaPoint retains the range of simultaneous readings, rather than silently
// selecting the highest. IDs link every constituent to immutable raw evidence.
type quotaPoint struct {
	Observation
	Low  float64  `json:"low"`
	High float64  `json:"high"`
	IDs  []string `json:"ids"`
}

func observationPoint(o Observation) quotaPoint {
	p := quotaPoint{Observation: o, IDs: []string{o.ID}}
	if o.Used != nil {
		p.Low, p.High = *o.Used-.5, *o.Used+.5
	}
	if p.TimeLow == 0 && p.TimeHigh == 0 {
		switch o.Source {
		case "response_header":
			p.TimeLow, p.TimeHigh, p.TimeSource = max(int64(1), o.Observed-quotaClockMarginMS), o.Observed+1000+quotaClockMarginMS, "legacy_provider_date_with_clock_margin"
		case "":
			p.TimeLow, p.TimeHigh, p.TimeSource = o.Observed, o.Observed, "exact"
		default:
			p.TimeSource = "unknown"
		}
	}
	return p
}

func quotaPoints(w Window, observations []Observation, events []Event) []quotaPoint {
	byEvent := map[int64]*Event{}
	ids := make(map[string]bool, len(w.ObservationIDs))
	for _, id := range w.ObservationIDs {
		ids[id] = true
	}
	points := []quotaPoint{}
	for _, o := range observations {
		if !ids[o.ID] || o.Used == nil || !finite(*o.Used) || *o.Used < 0 || *o.Used > 100 || o.Observed < w.Start || o.Observed >= w.Reset {
			continue
		}
		if o.TimeSource == "" && o.EventID > 0 {
			byEvent[o.EventID] = nil
		}
		points = append(points, observationPoint(o))
	}
	for i := range events {
		if _, needed := byEvent[events[i].ID]; needed {
			byEvent[events[i].ID] = &events[i]
		}
	}
	for i := range points {
		if e := byEvent[points[i].EventID]; e != nil {
			points[i].Observation = withEventTiming(points[i].Observation, *e)
		}

		points[i].TimeLow = max(points[i].TimeLow, w.Start)
		points[i].TimeHigh = min(points[i].TimeHigh, w.Reset)
	}
	sort.Slice(points, func(i, j int) bool {
		if points[i].Observed == points[j].Observed {
			return points[i].ID < points[j].ID
		}
		return points[i].Observed < points[j].Observed
	})
	out := []quotaPoint{}
	for _, p := range points {
		if len(out) == 0 || out[len(out)-1].Observed != p.Observed {
			out = append(out, p)
			continue
		}
		prev := &out[len(out)-1]
		prev.Low, prev.High = math.Min(prev.Low, p.Low), math.Max(prev.High, p.High)
		v := (prev.Low + prev.High) / 2
		prev.Used = &v
		prev.IDs = append(prev.IDs, p.IDs...)
		prev.TimeLow, prev.TimeHigh = min(prev.TimeLow, p.TimeLow), max(prev.TimeHigh, p.TimeHigh)
		prev.Received = max(prev.Received, p.Received)
		if prev.Source != p.Source {
			prev.Source = "mixed"
		}
		if !timedPoint(p) {
			prev.TimeSource = "unknown"
		}
	}
	plan := ""
	for i := range out {
		if out[i].PlanType != "" {
			plan = out[i].PlanType
		}
		out[i].PlanType = plan
	}
	return out
}

func timedPoint(p quotaPoint) bool {
	return p.TimeSource != "unknown" && p.TimeSource != "clock_conflict" && p.TimeLow > 0 && p.TimeHigh >= p.TimeLow
}
func finite(v float64) bool { return !math.IsNaN(v) && !math.IsInf(v, 0) }
